{"command": "cd $DOCUMENTS_DIR && python3 - <<'EOF'
import openpyxl
wb = openpyxl.load_workbook('rent-roll-lease-abstracts.xlsx', data_only=True)
print(wb.sheetnames)
ws = wb['Vacancy Schedule']
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, values_only=True):
    cells = [str(c) for c in row if c not in (None,'')]
    if cells:
        print(' | '.join(cells)[:1200])
EOF"}

