import subprocess, re
out=subprocess.run(['pdftotext','-bbox','mortgage-and-security-agreement.pdf','-'],capture_output=True,text=True).stdout
# find page containing WITNESSES
pages=out.split('<page ')
for i,pg in enumerate(pages):
    if 'WITNESSES:' in pg:
        print("page", i)
        words=re.findall(r'<word xMin="([0-9.]+)" yMin="([0-9.]+)" xMax="([0-9.]+)" yMax="([0-9.]+)">([^<]*)</word>', pg)
        ys={}
        for xm,ym,xM,yM,t in words:
            ys.setdefault(round(float(ym)), []).append((float(xm),float(xM),t))
        for y in sorted(ys)[:14]:
            row=ys[y]
            print(y, " | ".join(f"{t}@{x0:.0f}-{x1:.0f}" for x0,x1,t in row[:6]))
        break
EOF"}

